INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (19,19,'["Comment définissez-vous un plan de communication adapté à une institution publique régionale, et quels outils utiliseriez-vous pour mesurer son impact ?", "Quelles étapes suivez-vous pour concevoir et piloter un événement institutionnel de bout en bout, du brief client à l''évaluation post-événement ?", "Comment assurez-vous la cohérence d''une identité de marque territoriale à travers différents supports de communication (print, digital, événementiel) ?", "Parlez-moi d''un projet concret que vous avez géré seul durant vos 3 années d''expérience, en précisant votre rôle exact et les résultats obtenus.", "Avez-vous déjà travaillé avec des parties prenantes multiples (élus, partenaires institutionnels, prestataires) ? Comment avez-vous géré les désaccords ou les priorités contradictoires ?", "Votre formation est orientée marketing et événementiel privé — comment avez-vous développé des compétences applicables à un contexte institutionnel ou public ?", "Pourquoi postulez-vous à l''ADER Fès-Meknès plutôt qu''à une agence de communication ou une entreprise privée ?", "Où vous voyez-vous professionnellement dans 3 ans, et en quoi ce poste s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions principales de l''ADER Fès-Meknès et de son rôle dans le développement économique de la région ?", "Quelle est, selon vous, la différence fondamentale entre la communication d''une institution publique comme l''ADER et celle d''une entreprise commerciale ?"]','[]','{}','2026-08-27 13:29:32.795784') ON CONFLICT (id) DO NOTHING;